hold on; grid on; box off;
try, set(gca, 'GridColor', [0.80 0.80 0.80], 'GridAlpha', 0.6); catch, end
dE = [-2.85 -0.39 -4.41 -1.16 -4.92 -1.73];
stem(1:6, dE, 'filled', 'LineWidth', 3, 'Color', [0.384 0.314 0.839], 'MarkerFaceColor', [0.384 0.314 0.839], 'MarkerSize', 8);
set(gca, 'XTick', 1:6, 'XTickLabel', {'FeCl_2, U=0', 'FeCl_2, U=4', 'CoCl_2, U=0', 'CoCl_2, U=4', 'NiCl_2, U=0', 'NiCl_2, U=4'});
try, set(gca, 'XTickLabelRotation', 35); catch, end
plot([0.4 6.6], [0 0], 'k-');
ylabel('E_{AFM} - E_{FM} (meV per formula unit)');
title('Interlayer antiferromagnetic order is lower in every case (few meV)');
